begin;
set local search_path=public,private,extensions;
select plan(11);
select ok(has_function_privilege('authenticated','public.get_my_yousign_preparation_v1(uuid)','EXECUTE'),'signer workspace is callable by authenticated humans');
select ok(has_function_privilege('authenticated','public.get_my_yousign_preparations_v1()','EXECUTE'),'pending preparations are available to authenticated humans');
select ok(not has_function_privilege('anon','public.get_my_yousign_preparation_v1(uuid)','EXECUTE') and not has_function_privilege('service_role','public.get_my_yousign_preparation_v1(uuid)','EXECUTE'),'anonymous and worker roles cannot impersonate a signer');
select ok(not has_function_privilege('authenticated','private.my_yousign_preparation_signer_v1(uuid)','EXECUTE'),'internal identity projection is not a direct user API');
select ok(has_function_privilege('authenticated','public.get_my_yousign_preparation_for_signer_v1(uuid)','EXECUTE') and not has_function_privilege('anon','public.get_my_yousign_preparation_for_signer_v1(uuid)','EXECUTE') and not has_function_privilege('service_role','public.get_my_yousign_preparation_for_signer_v1(uuid)','EXECUTE'),'exact signer lookup is a human-only API');
select set_config('request.jwt.claim.sub','',true);
select set_config('request.jwt.claims','{"role":"authenticated"}',true);
select throws_ok($$select public.get_my_yousign_preparations_v1()$$,'42501','YOUSIGN_PREPARATION_DENIED','no actor cannot list preparations');
select throws_ok($$select public.get_my_yousign_preparation_v1('ab940000-0000-4000-8000-000000000099')$$,'42501','YOUSIGN_PREPARATION_DENIED','no actor cannot select a guessed envelope');
select throws_ok($$select public.get_my_yousign_preparation_for_signer_v1('ab940000-0000-4000-8000-000000000099')$$,'42501','YOUSIGN_PREPARATION_DENIED','no actor cannot select a guessed signer');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select throws_ok($$select public.get_my_yousign_preparations_v1()$$,'42501','YOUSIGN_PREPARATION_DENIED','service JWT is not a human preparation session');
select throws_ok($$select public.get_my_yousign_preparation_for_signer_v1('ab940000-0000-4000-8000-000000000099')$$,'42501','YOUSIGN_PREPARATION_DENIED','service JWT cannot resolve a human signer workspace');
select ok((select p.prosecdef and p.provolatile='s' from pg_proc p where p.oid='public.get_my_yousign_preparation_v1(uuid)'::regprocedure),'workspace reads are stable security-definer projections');
select * from finish();
rollback;
